/*
 * A071024  Triangle read by rows giving successive states of cellular
 *          automaton generated by "Rule 92".
 * https://oeis.org/A071024
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   not stated
 * Range:     u8 n <= 98, u16 n <= 98, u32 n <= 98, u64 n <= 98, u128 n <= 98,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Computes OEIS A071024: Rule 92 cellular automaton triangle read by rows */
#include <stdint.h>
#include <stdlib.h>
#include <stddef.h>

/* flattened cells of the triangle */
static uint8_t *triangle = NULL;
/* highest row that has been fully computed (row numbering starts at 0) */
static idx_t   maxComputedRow = 0;
/* number of allocated elements */
static size_t  capacity      = 0;

/* find the row r such that r*(r+1)/2 ≤ n < (r+1)*(r+2)/2 */
static inline idx_t find_row(idx_t n)
{
    if (n == 0) return 0;
    idx_t low  = 0;
    idx_t high = 1;
    while (((unsigned __int128)(high + 1) * (high + 2)) / 2 <= n)
        high <<= 1;
    while (low < high) {
        idx_t mid = low + (high - low) / 2;
        if (((unsigned __int128)(mid + 1) * (mid + 2)) / 2 <= n)
            low = mid + 1;
        else
            high = mid;
    }
    return low;
}

/* enlarge the triangle storage to at least 'needed' cells */
static inline void ensure_capacity(size_t needed)
{
    if (capacity >= needed) return;
    size_t newcap = capacity ? capacity * 2 : 1;
    while (newcap < needed) newcap <<= 1;
    uint8_t *tmp = (uint8_t *)realloc(triangle, newcap);
    if (!tmp) abort();            /* allocation failure is fatal */
    triangle = tmp;
    capacity = newcap;
}

/* compute all rows from (maxComputedRow+1) up to 'upper' (inclusive) */
static inline void compute_rows_up_to(idx_t upper)
{
    if (upper <= maxComputedRow) return;

    /* Rule 92 bits: 111→0,110→1,101→0,100→1,011→1,010→1,001→0,000→0 */
    const uint8_t rulebits = 92u;      /* 01011100b */

    size_t needed = (upper + 2) * (upper + 1) / 2;
    ensure_capacity(needed);

    for (idx_t rr = maxComputedRow + 1; rr <= upper; ++rr) {
        idx_t prev_len   = rr;                     /* length of previous row (rr-1) = rr cells */
        idx_t prevStart  = (rr - 1) * rr / 2;       /* start index of row rr-1 */
        idx_t newStart   = rr * (rr + 1) / 2;       /* start index of row rr   */

        for (idx_t q = 0; q <= rr; ++q) {
            uint8_t left   = (q == 0) ? 0 : triangle[prevStart + q - 1];
            uint8_t center = (q == rr) ? 0 : triangle[prevStart + q];
            uint8_t right  = (q + 1 >= prev_len) ? 0 : triangle[prevStart + q + 1];

            uint8_t idx    = (left << 2) | (center << 1) | right;
            uint8_t val    = (rulebits >> idx) & 1;
            triangle[newStart + q] = val;
        }
    }
    maxComputedRow = upper;
}

seq_t a(idx_t n)
{
    /* lazy initialization: create the first row */
    if (!triangle) {
        capacity = 1;
        triangle = (uint8_t *)malloc(1);
        if (!triangle) abort();
        triangle[0] = 1;   /* row 0 */
        maxComputedRow = 0;
    }

    idx_t r = find_row(n);
    compute_rows_up_to(r);

    idx_t rowStart = r * (r + 1) / 2;
    idx_t pos = n - rowStart;
    return (seq_t)triangle[rowStart + pos];
}
